from chapter07_common import *

B = Block('theory')
PAGES = {54:[139,140,141,142],55:[142,143,144],56:[144],57:[146,147],58:[147,148,149],59:[149,150],60:[152,153],61:[154,155],62:[155,156]}
NUMERIC = []

def area(p, names):
    return abs(sum(p[names[i]][0]*p[names[(i+1)%len(names)]][1]-p[names[(i+1)%len(names)]][0]*p[names[i]][1] for i in range(len(names))))/2

def verify(name, actual, expected):
    assert math.isclose(actual,expected,rel_tol=1e-9,abs_tol=1e-9),(name,actual,expected)
    NUMERIC.append(dict(name=name,actual=actual,expected=expected))

def add(n,title,statement,answer,rows,p,v,views=None,checks=(),cases=(),**kw):
    B.add(n,'single',statement,answer,rows,p,v,views,checks,cases,collection='theory',title=title,printed=PAGES[n],**kw)

def question(n,statement,answer,rows,p,v,views=None,checks=(),cases=(),**kw):
    B.add(n,'single',statement,answer,rows,p,v,views,checks,cases,collection='selfcheck',title='Вопрос '+str(n),printed=[158],**kw)

def case_steps(mapping):
    """A step displays the actual independently normalized case, not a stale base scene."""
    views=B.models[-1]['model']['views']
    for step,case in mapping.items():
        views['step-'+str(step)]={**deepcopy(views['case-'+str(case)]),'label':'Шаг '+str(step)}

def grid(w,h,dx=1):
    p=dict(A=[0,0],B=[w,0],C=[w,h],D=[0,h]); lines=[]
    for axis,limit,other in [('x',w,h),('y',h,w)]:
        for i in range(1,math.ceil(limit/dx)):
            q=i*dx
            if q>=limit-1e-10:continue
            a=f'_{axis}{i}a';b=f'_{axis}{i}b'
            p[a]=[q,0] if axis=='x' else [0,q]
            p[b]=[q,other] if axis=='x' else [other,q]
            lines.append([a,b])
    return p,sc('ABCD',poly(),dashSegments=lines)

