rectcase=rect(6,4);rcv=sc('ABCD',poly(),rightAngles=[rt('D','A','B')])
paraproof=[
 row('Как правильно выбрать высоту?','Возьмём AD за основание a. Высота h — перпендикуляр от точки противоположной стороны к прямой AD, а не наклонная боковая сторона. В параллелограмме расстояние между прямыми AD и BC постоянно.','Определение высоты; расстояние между параллельными прямыми.',[37,57]),
 row('Какие вспомогательные отрезки проведём?','Опустим перпендикуляры BH и CK к прямой AD. Назовём вершины так, чтобы угол BAD был острым или прямым. При остром угле H лежит на луче AD: внутри AD, в D или за D. При прямом угле исходная фигура уже является прямоугольником.','Перпендикуляры к одной прямой параллельны; свойства углов параллелограмма.',[29,48,57]),
 row('Почему отсечённые треугольники имеют равные площади?','Для острого угла прямоугольные ABH и DCK равны: AB =DC как противоположные стороны, а углы BAH и CDK равны при AB ∥DC. Это равенство по гипотенузе и острому углу. Поэтому площади ABH и DCK совпадают.','Признак равенства прямоугольных треугольников.',[36,48,54]),
 row('Как сравнить параллелограмм с прямоугольником?','Трапеция ABCK состоит из параллелограмма ABCD и треугольника DCK. Та же трапеция состоит из прямоугольника HBCK и треугольника ABH. Вычитая равные площади треугольников, получаем равенство площадей ABCD и HBCK. Это разбиение верно и при H =D, и при H за D.','Сложение и вычитание площадей частей.',54),
 row('Как закончить доказательство?','У прямоугольника HBCK стороны BC =AD =a и BH =h. Поэтому его площадь ah; такой же будет площадь параллелограмма. Если H =A, формула сразу следует из площади прямоугольника. Все положения основания высоты учтены.','Формула площади прямоугольника.',[48,56,57])
]
