triproof=[
 row('Какой отрезок считать высотой?','Выберем сторону AB основанием a. Высота CH проведена из C перпендикулярно прямой AB. Основание высоты может находиться внутри AB, в вершине или на продолжении стороны; длина высоты всегда положительна.','Определение высоты треугольника.',[17,58]),
 row('Как достроить треугольник?','Через C проведём прямую, параллельную AB, а через B — прямую, параллельную AC. Их пересечение D даёт параллелограмм ABDC. Диагональ BC делит его на треугольники ABC и DCB.','Построение параллелограмма.',[28,48]),
 row('Почему берём ровно половину?','У ABC и DCB общая сторона BC, а AB =CD и AC =BD как противоположные стороны параллелограмма. По трём сторонам треугольники равны, значит равновелики. Площадь параллелограмма равна AB·CH, поэтому SABC =AB·CH/2 =ah/2.','Равенство треугольников, площади равных фигур, площадь параллелограмма.',[20,54,57]),
 row('Что получается для прямоугольного треугольника?','Если один катет выбран основанием, другой катет перпендикулярен ему и является высотой. Поэтому площадь равна половине произведения катетов: S =ab/2.','Следствие формулы площади треугольника.',58)
]
heightrow=row('Как сравнивать треугольники с равными высотами?','Если высоты h равны, то S₁/S₂ =(a₁h/2)/(a₂h/2) =a₁/a₂. Поэтому при общей высоте площади относятся как основания; равные основания при равных высотах дают равные площади.','Сокращение одинаковых положительных множителей.',58)
anglerows=[
 row('Как использовать равные углы?','Пусть ∠A =∠A₁ в треугольниках ABC и A₁B₁C₁. Совместим вершины этих углов, а стороны направим по одним лучам. Так вершина A₁ оказывается в A. Рассмотрим промежуточный треугольник AB₁C.','Перемещение фигуры сохраняет площадь; равные углы можно совместить.',[54,58]),
 row('Как получить два простых отношения?','У ABC и AB₁C высота из C к прямой AB одна и та же, поэтому SABC/SAB₁C =AB/AB₁. У AB₁C и AB₁C₁ общая высота из B₁ к прямой AC, поэтому SAB₁C/SAB₁C₁ =AC/AC₁.','Отношение площадей при равных высотах.',58),
 row('Что даст умножение отношений?','Умножая равенства, сокращаем площадь промежуточного треугольника: SABC/SA₁B₁C₁ =(AB·AC)/(A₁B₁·A₁C₁). Берём именно стороны, между которыми заключены равные углы. Никакого предположения о подобии здесь не требуется.','Произведение отношений и сохранение площади при совмещении.',[54,58])
]
inrows=[
 row('Как использовать вписанную окружность?','Соединим её центр O с вершинами A, B, C. Получаются три треугольника без перекрытий. Перпендикуляры из O к AB, BC, CA — радиусы окружности к точкам касания, поэтому все три высоты равны r.','Вписанная окружность; радиус в точке касания перпендикулярен касательной.',[42,43,58]),
 row('Почему получается S =pr?','Складываем площади: S =(AB·r +BC·r +CA·r)/2 =((AB +BC +CA)/2)·r =pr. Здесь p — полупериметр, то есть половина периметра, а r — радиус вписанной окружности.','Сложение площадей и вынесение общего множителя.',[54,58])
]
add(58,'Площадь треугольника','Основание и высота треугольника; площадь, её отношения и формула через вписанную окружность.','S =ah/2; при равных высотах S₁/S₂ =a₁/a₂; при равных углах — отношение произведений прилежащих сторон; S =pr.',triproof+[heightrow]+anglerows+inrows,tp,tv,[tf,tg,tt,tf,tf,tf,tf,tf,tf,tf],checks=[perp('C','H','A','B'),par('A','B','C','D'),par('A','C','B','D')],cases=[(tright,trv,'Прямоугольный треугольник',4),(toutside,tov,'Высота на продолжении стороны',1,[perp('C','H','A','B')]),(hp,hv,'Общая высота и разные основания',5),(ap,av2,'Равные углы и промежуточный треугольник',7,[col('A','B1','B'),col('A','C','C1'),perp('C','H','A','B'),perp('B1','H1','A','C')],{'B1':'B₁','C1':'C₁','H1':'H₁'}),(ip,iv1,'Три высоты равны радиусу',9,[equal(('O','K'),('O','L'),('O','M')),perp('O','K','A','B'),perp('O','L','B','C'),perp('O','M','A','C')])])
case_steps({4:1,5:3,6:4,7:4,8:4,9:5,10:5})
