zo=dict(A=[0,0],B=[9,3],C=[13,3],D=[8,0],H=[9,0],K=[8,3]);zov=sc('ABCDHK',poly()+[['B','D'],['B','H'],['D','K']],dashSegments=[['D','H'],['K','B']],rightAngles=[rt('B','H','D'),rt('D','K','B')])
traprows=[
 row('Какие отрезки входят в формулу?','Основания a и b — параллельные стороны AD и BC. Высота h — перпендикулярное расстояние между содержащими их прямыми. Проведём BH и DK; их длины равны h.','Определение высоты трапеции; расстояние между параллельными прямыми.',[37,50,59]),
 row('Как разбить трапецию?','Диагональ BD делит её на треугольники ABD и BCD без перекрытия внутренних областей. Для ABD берём основание AD, для BCD — основание BC.','Разбиение выпуклого четырёхугольника диагональю.',[46,54]),
 row('Чему равны площади двух частей?','Высота ABD к AD равна BH =h, поэтому SABD =AD·h/2. Высота BCD к BC равна DK =h, поэтому SBCD =BC·h/2. Высота может падать на продолжение основания; формула треугольника сохраняется.','Площадь треугольника.',58),
 row('Как получить площадь целого?','Складываем: S =AD·h/2 +BC·h/2 =(AD +BC)h/2 =(a +b)h/2. Это полусумма оснований, умноженная на высоту. Вместо оснований нельзя подставлять боковые стороны.','Сложение площадей и вынесение общего множителя.',[54,59])
]
zc=[par('A','D','B','C'),perp('B','H','A','D'),perp('D','K','B','C'),equal(('B','H'),('D','K'))]
