# 60. Four congruent right triangles; the central square is proved first.
py=dict(A=[0,0],B=[4,0],C=[0,3],D=[7,0],E=[7,7],F=[0,7],G=[7,4],H=[3,7]);pyv=sc('ABC',tri(),rightAngles=[rt('B','A','C')]);pyf=more(pyv,'DEFGH',[['B','D'],['D','G'],['G','E'],['E','H'],['H','F'],['F','C'],['B','G'],['G','H'],['H','C']]);pye=more(pyf,equalSegments=[eq('B','C'),eq('B','G'),eq('G','H'),eq('H','C')]);pyg=more(pye,polygons=[['B','G','H','C']],rightAngles=[rt('B','A','C'),rt('C','B','G')])
pyrows=[
 row('Как обозначить стороны правильно?','В прямоугольном треугольнике a и b — катеты, c — гипотенуза, лежащая напротив прямого угла. Докажем c² =a² +b² с помощью площадей.','Формулировка теоремы Пифагора.',60),
 row('Как расположить четыре равных треугольника?','Внутри квадрата со стороной a +b разместим по углам четыре копии данного прямоугольного треугольника. Их катеты идут вдоль сторон большого квадрата, а гипотенузы ограничивают внутренний четырёхугольник. Все четыре треугольника равны по двум катетам.','Построение и признак равенства прямоугольных треугольников.',36),
 row('Почему внутренний четырёхугольник — квадрат?','Все его стороны — гипотенузы равных треугольников, значит они равны c. Острые углы прямоугольного треугольника в сумме равны 90°. Поэтому каждый внутренний угол оставшегося четырёхугольника равен 180° −90° =90°. Это квадрат со стороной c.','Сумма углов треугольника; определение квадрата.',[31,52]),
 row('Как сравнить две записи площади?','Большой квадрат имеет площадь (a +b)². Он состоит из четырёх треугольников площадью ab/2 каждый и внутреннего квадрата площадью c². Поэтому (a +b)² =4·ab/2 +c² =2ab +c².','Площади квадрата и прямоугольного треугольника; сложение площадей.',[54,55,58]),
 row('Как получить искомое равенство?','После раскрытия скобок a² +2ab +b² =2ab +c². Вычитая 2ab, получаем c² =a² +b². Для длины гипотенузы c =√(a² +b²), а для катета a =√(c² −b²); длины берутся положительными.','Равносильные преобразования и положительность длин.',60)
]
pyc=[perp('A','B','A','C'),equal(('B','C'),('B','G'),('G','H'),('H','C')),perp('C','B','B','G')]
add(60,'Теорема Пифагора','Докажите связь между катетами и гипотенузой прямоугольного треугольника с помощью площадей.','c² =a² +b².',pyrows,py,pyv,[pyv,pyf,pyg,pyg,pyg],checks=pyc)
