# 61. Do not mark the sought right angle before the SSS proof.
cp=dict(A=[0,3],B=[4,0],C=[0,0]);cv=sc('ABC',tri());cg=more(cv,rightAngles=[rt('A','C','B')]);construction=deepcopy(cp);consv=sc('ABC',tri(),rightAngles=[rt('A','C','B')])
converse=[
 row('Что дано, а что требуется доказать?','Дан треугольник ABC, для которого AB² =AC² +BC². Прямой угол пока не предполагается. Нужно доказать, что именно угол C, лежащий напротив AB, равен 90°.','Условие обратной теоремы.',61),
 row('Как построить фигуру для сравнения?','Построим прямоугольный треугольник A₁B₁C₁ с катетами A₁C₁ =AC и B₁C₁ =BC. По уже доказанной теореме Пифагора A₁B₁² =AC² +BC² =AB², поэтому A₁B₁ =AB.','Теорема Пифагора в построенном прямоугольном треугольнике.',60),
 row('Почему исходный треугольник тоже прямоугольный?','Треугольники ABC и A₁B₁C₁ равны по трём сторонам. Значит, соответствующие углы C и C₁ равны. Построенный угол C₁ прямой, следовательно ∠C =90°. Только теперь отмечаем прямой угол в исходной фигуре.','Третий признак равенства треугольников.',20)
]
triples=[
 row('Какие треугольники называются пифагоровыми?','Это прямоугольные треугольники, длины всех трёх сторон которых выражаются целыми числами в выбранной единице длины. Для проверки нужно установить c² =a² +b², взяв c самой большой стороной.','Определение и обратная теорема Пифагора.',61),
 row('Как проверить несколько примеров?','Для 3,4,5: 9 +16 =25. Для 5,12,13: 25 +144 =169. Для 8,15,17: 64 +225 =289. Для 7,24,25: 49 +576 =625. Во всех случаях обратная теорема даёт прямой угол напротив большей стороны.','Проверка равенства квадратов.',61),
 row('Как получать целочисленные примеры формулой?','Возьмём натуральные k,m,n, где m >n. Числа 2kmn, k(m² −n²), k(m² +n²) положительны. Сумма квадратов первых двух равна k²[4m²n² +(m² −n²)²] =k²(m² +n²)². Они образуют прямоугольный треугольник; это способ получать пифагоровы тройки.','Тождество и обратная теорема Пифагора.',61)
]
add(61,'Теорема, обратная теореме Пифагора','Докажите признак прямоугольного треугольника по сторонам; разберите пифагоровы треугольники.','Если c² =a² +b², угол напротив c — прямой. Примеры целочисленных сторон: 3,4,5 и 5,12,13.',converse+triples,cp,cv,[cv,cv,cg,cg,cg,cg],checks=[perp('C','A','C','B')],cases=[(construction,consv,'Вспомогательный прямоугольный треугольник',2,[],{'A':'A₁','B':'B₁','C':'C₁'})])
