# 62. Symmetry in the side lengths lets us choose the base between acute angles.
her=dict(A=[0,0],B=[7,0],C=[2,4],H=[2,0]);herv=sc('ABC',tri());herf=more(herv,'H',[['C','H']],rightAngles=[rt('C','H','B')]);herleft=more(herf,polygons=[['A','C','H']]);herright=more(herf,polygons=[['H','C','B']])
heron=[
 row('Какие обозначения нужны?','Пусть стороны треугольника a =BC, b =CA, c =AB, а p =(a +b +c)/2. Они положительны и удовлетворяют строгим неравенствам треугольника, поэтому p −a, p −b и p −c положительны.','Неравенство треугольника; определение полупериметра.',[34,62]),
 row('Почему можно расположить высоту внутри основания?','У любого треугольника как минимум два угла острые. Назовём их A и B и возьмём AB за основание. Тогда основание H высоты CH лежит внутри AB. Обозначим CH =h, AH =y, HB =x; x +y =c. Итоговая формула симметрична относительно сторон, поэтому такой выбор обозначений не ограничивает треугольник.','Сумма углов треугольника; свойство высоты между острыми углами.',[31,62]),
 row('Как исключить x из равенств Пифагора?','Из прямоугольных ACH и BCH: b² =h² +y², a² =h² +x². Вычитая, получаем y² −x² =b² −a². Так как y +x =c, имеем y −x =(b² −a²)/c. Складывая с y +x =c, находим y =(b² +c² −a²)/(2c).','Теорема Пифагора и разность квадратов.',60),
 row('Как выразить h² только через стороны?','Подставим y в h² =b² −y². После умножения на 4c² получим: 4c²h² =4b²c² −(b² +c² −a²)² =[(b +c)² −a²]·[a² −(b −c)²]. Это повторное применение разности квадратов.','Алгебраическое тождество после подстановки.',[60,62]),
 row('Как появляется полупериметр?','Раскроем оба множителя как разности квадратов: 4c²h² =(a +b +c)(b +c −a)(a +c −b)(a +b −c). Эти четыре множителя равны 2p, 2(p −a), 2(p −b), 2(p −c). Поэтому 4c²h² =16p(p −a)(p −b)(p −c).','Определение p и разложение разности квадратов.',62),
 row('Как перейти от высоты к площади?','Площадь S =ch/2, значит S² =c²h²/4 =p(p −a)(p −b)(p −c). Площадь положительна, поэтому S =√[p(p −a)(p −b)(p −c)]. Формула применима к любому невырожденному треугольнику.', 'Формула площади треугольника и положительный квадратный корень.',[58,62])
]
