question(12,'Какая формула площади треугольника называется формулой Герона? Выведите эту формулу.','S =√[p(p −a)(p −b)(p −c)], где p — полупериметр.',heron,her,herv,[herv,herf,herleft,herright,herf,herf],checks=[perp('C','H','A','B'),col('A','H','B')])
ha=dist(her['B'],her['C']);hb=dist(her['C'],her['A']);hc=dist(her['A'],her['B']);hs=(ha+hb+hc)/2
verify('Heron actual model',area(her,'ABC'),math.sqrt(hs*(hs-ha)*(hs-hb)*(hs-hc)))

def selfcheck():
    # These independent algebraic identities exercise varied shapes; they do not
    # certify source/pedagogy or replace the later non-author review.
    families=0
    for base in [1,2.5,6,11]:
        for height in [.5,2,4,9]:
            for shift in [-9,-1,0,1,7,17]:
                p=dict(A=[0,0],B=[base,0],C=[shift,height]);a=dist(p['B'],p['C']);b=dist(p['C'],p['A']);c=base;s=(a+b+c)/2
                assert math.isclose(area(p,'ABC'),base*height/2,rel_tol=1e-10)
                assert math.isclose(area(p,'ABC')**2,s*(s-a)*(s-b)*(s-c),rel_tol=1e-8,abs_tol=1e-8)
                families+=1
    for m in range(2,14):
        for n in range(1,m):
            for k in [1,2,5]:
                a=2*k*m*n;b=k*(m*m-n*n);c=k*(m*m+n*n)
                assert a*a+b*b==c*c and a+b>c
                families+=1
    from check_models import validate
    problems=[]
    for item in B.models:
        problems.extend((item['collection'],item['number'],x) for x in validate(item['model']))
    assert not problems,problems
    assert [x['number'] for x in B.theory]==list(range(54,63))
    assert [x['number'] for x in B.selfchecks]==list(range(1,13))
    return dict(authorOnly=True,modelRecords=len(B.models),numericChecks=len(NUMERIC),parameterFamilies=families,areaIdentities=NUMERIC)

if __name__=='__main__':
    result=selfcheck();B.write()
    p=COURSE/'preparation/chapter-07-theory.json';content=json.loads(p.read_text());content['authorNumericSelfCheck']=result;p.write_text(json.dumps(content,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({k:v for k,v in result.items() if k!='areaIdentities'}))
